useFilesState(page)
const below = page.graph.childrenOf(entry)
const hasBelow = below.length > 0 || entry.children_left_out > 0
const isOpen = page.graph.isOpen(entry)
return (
  <li className="graph-entry">
    <span className={`graph-row ${page.graph.isSelected(entry) ? 'is-selected' : ''}`}>
      {hasBelow ? (
        <button className="graph-toggle" aria-expanded={isOpen} aria-label={`${isOpen ? 'Close' : 'Open'} ${entry.name}`} onClick={() => void page.graph.toggle(entry)}>
          {isOpen ? '▾' : '▸'}
        </button>
      ) : (
        <span className="graph-toggle" />
      )}
      <button className="graph-node" aria-pressed={page.graph.isSelected(entry)} title={`${entry.type} ${entry.name}`} onClick={event => void page.graph.select(entry, isAlso(event))}>
        {entry.name}
      </button>
      <span className="graph-type">{entry.type}</span>
    </span>
    {isOpen && below.length ? (
      <ul className="graph-tree">
        {below.map(child => (
          <GraphEntryView key={child.node_id} page={page} entry={child} />
        ))}
      </ul>
    ) : null}
  </li>
)

const { graph } = useFilesState(page)
if (graph.problem) return <p className="files-note">{graph.problem}</p>
if (graph.isReading && !graph.trees) return <p className="files-note">Reading the session's graph…</p>
if (!graph.trees?.length) return <p className="files-note">The graph holds no node of these files.</p>
return (
  <ul className="graph-tree" aria-label="Graph">
    {graph.trees.map(tree => (
      <GraphEntryView key={tree.node_id} page={page} entry={tree} />
    ))}
  </ul>
)

const fidelities = this.stages.flatMap(stage => this.practices.map(key => FIDELITIES[stage]![key]).filter((slug): slug is string => Boolean(slug)))
return {
  version: this.version,
  is_stage_chosen: true,
  stages: Object.keys(FIDELITIES).map(name => ({ name, title: name, is_selected: this.stages.includes(name) })),
  practices: PRACTICES.map(practice => ({ ...practice, is_selected: this.practices.includes(practice.key) })),
  formats: [],
  fidelities,
} as GuidanceSelectionData

const below = CHECKOUT_FLOW_NODES.filter(child => child.parent === node.id && this.holds(child, paths))
if (!isOpened) return { node_id: node.id, name: node.name, type: node.type, children: [], children_left_out: below.length }
return { node_id: node.id, name: node.name, type: node.type, children: below.map(child => this.entry(child, paths, false)), children_left_out: 0 }

const readWhenStale = () => {
  const { fileBar, graph } = this.store.state
  if (fileBar.view === 'graph' && !graph.isReading && graph.readFor !== this.paths.join('\n')) void this.read()
}
readWhenStale()
return this.store.subscribe(readWhenStale)

const paths = this.paths
const readFor = paths.join('\n')
this.store.change(({ graph }) => ({ graph: { ...graph, readFor, isReading: true, problem: '' } }))
try {
  const trees = (await this.session.graphTrees(paths)) ?? []
  this.store.change(({ graph }) => (graph.readFor === readFor ? { graph: { ...graph, trees, branches: {}, isReading: false } } : {}))
} catch (failure) {
  this.store.change(({ graph }) => ({ graph: { ...graph, isReading: false, problem: `The graph did not read: ${reasonOf(failure)}` } }))
  this.notices.fail(`The Files app did not read the session's graph: ${reasonOf(failure)}`, 'Showing the graph view, calling session.graph_trees')
}

const isOpen = this.isOpen(entry)
this.store.change(({ graph }) => ({ graph: { ...graph, openNodes: isOpen ? graph.openNodes.filter(id => id !== entry.node_id) : [...graph.openNodes, entry.node_id] } }))
if (isOpen || !entry.children_left_out || this.store.state.graph.branches[entry.node_id]) return
try {
  const branch = await this.session.graphBranch(entry.node_id, this.paths)
  if (branch) this.store.change(({ graph }) => ({ graph: { ...graph, branches: { ...graph.branches, [entry.node_id]: branch } } }))
} catch (failure) {
  this.notices.fail(`The Files app did not open ${entry.name} in the graph: ${reasonOf(failure)}`, 'Opening a node in the graph view, calling session.graph_branch')
}

try {
  const lines = await this.session.graphNodeRange(entry.node_id)
  if (!lines) return
  const kept = also ? this.store.state.graph.selected.filter(selected => selected.nodeId !== entry.node_id) : []
  const selected = [...kept, { nodeId: entry.node_id, lines }]
  this.store.change(({ graph }) => ({ graph: { ...graph, selected } }))
  await this.showNodes(selected)
} catch (failure) {
  this.notices.fail(`The Files app did not open ${entry.name}: ${reasonOf(failure)}`, 'Selecting a node in the graph view, calling session.graph_node_range')
}

this.fileBar.restoreWidth()
const uncaught = (failure: unknown) => this.notices.fail(`The Files page met a failure nothing caught: ${reasonOf(failure)}`, 'An uncaught failure in the Files page')
const onError = (event: ErrorEvent) => uncaught(event.error ?? event.message)
const onRejection = (event: PromiseRejectionEvent) => uncaught(event.reason)
window.addEventListener('error', onError)
window.addEventListener('unhandledrejection', onRejection)
void this.list()
// A link naming no session, such as the app's bare address, has nothing to ask cdd about: list() says so.
if (this.link.namesFiles) void this.readPlace()
if (this.link.namesFiles && !this.link.isSessionFolder) void this.readRootFiles()
const stopFollowing = this.link.isSessionFolder || !this.link.namesFiles ? () => undefined : this.guidance.follow()
const stopGraph = this.graph.follow()
const reread = () => void this.refreshOpen()
window.addEventListener('focus', reread)
return () => {
  window.removeEventListener('error', onError)
  window.removeEventListener('unhandledrejection', onRejection)
  window.removeEventListener('focus', reread)
  stopFollowing()
  stopGraph()
  this.stopRefreshing()
}

try {
  const session = await this.session.show()
  if (session) this.store.change(() => ({ place: [session.repoName, session.branch, session.root].filter(Boolean).join(' · ') }))
} catch (failure) {
  this.notices.fail(`The Files app did not read where the session works: ${reasonOf(failure)}`, 'Opening the Files app, calling session.show')
}

if (!this.link.namesFiles) return this.store.change(() => ({ isListing: false, problem: 'This link names no files: open the Files app from the chat bar.' }))
try {
  const byFidelity = await this.filesByFidelity(this.listed)
  this.store.change(state => ({ byFidelity, isListing: false, entries: this.shownFrom({ ...state, byFidelity }) }))
  const entries = this.state.entries
  const first = this.link.file || entries.find(entry => entry.exists && !isDrawio(entry.path))?.path || ''
  if (first) await this.open(first)
} catch (failure) {
  this.store.change(() => ({ isListing: false, problem: `The files did not list: ${reasonOf(failure)}` }))
  this.notices.fail(`The Files app did not list the files: ${reasonOf(failure)}`, `Opening the Files app on ${this.link.subject}`, { isShownOnPage: true })
}

const formats = selectedFormatsOf(state.guidance)
if (this.link.isSessionFolder) return filesShown(state.byFidelity, [''], formats)
const listed = listedBy(state.guidance, this.link.fidelities)
return eachOnce([...filesShown(state.byFidelity, listed, formats), ...rootFilesShown(state.rootFiles ?? [], listed, formats, isNoPracticeSelected(state.guidance))])

try {
  const rootFiles = (await TicketClientGenerated.named(this.api, this.link.ticket).rootFiles()) ?? []
  this.store.change(state => ({ rootFiles, entries: this.shownFrom({ ...state, rootFiles }) }))
} catch (failure) {
  this.notices.fail(`The Files app did not list the files under the session's root: ${reasonOf(failure)}`, 'Opening the Files app, calling ticket.root_files')
}

if (this.link.isSessionFolder) return [{ slug: '', entries: (await this.session.folderFiles()) ?? [] }]
if (!slugs.length) return []
// One call for every fidelity, which shares one look at what the branch changed.
const bySlug = (await TicketClientGenerated.named(this.api, this.link.ticket).fidelityFiles(slugs)) ?? {}
return slugs.map(slug => {
  const byFormat = Object.entries(bySlug[slug] ?? {})
  const formatOf = Object.fromEntries(byFormat.flatMap(([format, entries]) => entries.map(entry => [entry.path, format])))
  return { slug, entries: byFormat.flatMap(([, entries]) => entries), formatOf }
})

this.store.change(state => ({ entries: this.shownFrom(state) }))
const missing = this.listed.filter(slug => !this.state.byFidelity.some(each => each.slug === slug))
if (this.link.isSessionFolder || this.state.isListing || !missing.length) return
try {
  const read = await this.filesByFidelity(missing)
  this.store.change(state => ({ byFidelity: [...state.byFidelity, ...read.filter(each => !state.byFidelity.some(held => held.slug === each.slug))] }))
  this.store.change(state => ({ entries: this.shownFrom(state) }))
} catch (failure) {
  this.notices.fail(`The Files app did not list the files of ${missing.join(', ')}: ${reasonOf(failure)}`, 'Showing the stages and practices selected')
}

const [first, ...others] = [...new Set(selected.map(node => node.lines.path))]
if (!first) return
if (this.state.openPath === first && this.state.file) await this.refreshOpen()
else await this.openAt(first)
const read = await Promise.all(others.map(path => this.session.file(path, true, this.state.reads.crossFile)))
this.store.change(() => ({ moreFiles: read.filter(file => file !== null) }))

this.store.change(() => ({ openPath: path, file: null }))
// A .drawio file shows in the draw.io editor beside the file list, which reads the file itself.
if (isDrawio(path)) return this.stopRefreshing()
await this.refreshOpen()

const path = this.state.openPath
if (!path) return
this.stopRefreshing()
try {
  const { rules, crossFile } = this.state.reads
  // A file opened from the graph view needs the folds its graph places, which only a read with rules answers.
  const file = await this.session.file(path, rules || this.state.graph.selected.length > 0, crossFile)
  if (this.state.openPath !== path) return
  this.store.change(() => ({ file, problem: '' }))
  if (file?.comments.some(comment => comment.state === 'sent')) this.refreshTimer = setTimeout(() => void this.refreshOpen(), SENT_REFRESH_MILLISECONDS)
} catch (failure) {
  this.store.change(() => ({ problem: `${path} did not open: ${reasonOf(failure)}` }))
  this.notices.fail(`The Files app did not open ${path}: ${reasonOf(failure)}`, `Opening ${path} in the Files app`, { isShownOnPage: true })
}
